<?php session_start();include 'config.php';if(!isset($_SESSION['doctor_id'])){header('Location:index.php');exit;}$doctor=(int)$_SESSION['doctor_id'];$user=(int)($_POST['user_id']??0);$text=trim($_POST['recommendation']??'');if($user&&$text!==''){$check=$conn->prepare('SELECT COUNT(*) c FROM appointments a JOIN doctors d ON d.full_name=a.doctor_name WHERE a.user_id=? AND d.id=?');$check->bind_param('ii',$user,$doctor);$check->execute();if((int)$check->get_result()->fetch_assoc()['c']>0){$s=$conn->prepare('INSERT INTO doctor_recommendations(doctor_id,user_id,recommendation) VALUES(?,?,?)');$s->bind_param('iis',$doctor,$user,$text);$s->execute();}}header('Location:doctor_dashboard.php#recommendations');exit;?>
